// PaymentSummary is the resolver for the paymentSummary field.
func (r *queryResolver) PaymentSummary(ctx context.Context, filter *model.PaymentFilter, dateRange *model.DateRange) (*model.PaymentSummary, error) {
	query := r.DB.Model(&model.Payment{})

	// Apply filters
	if filter != nil {
		query = helper.ApplyPaymentFilters(query, filter)
	}

	if dateRange != nil {
		if dateRange.From != nil {
			query = query.Where("created_at >= ?", dateRange.From)
		}
		if dateRange.To != nil {
			query = query.Where("created_at <= ?", dateRange.To)
		}
	}

	// Get totals by status
	var stats struct {
		Total       int64
		Successful  int64
		Failed      int64
		Pending     int64
		TotalAmount int64
	}

	// Count all payments
	baseQuery := r.DB.Model(&model.Payment{})
	if filter != nil {
		baseQuery = helper.ApplyPaymentFilters(baseQuery, filter)
	}
	if dateRange != nil {
		if dateRange.From != nil {
			baseQuery = baseQuery.Where("created_at >= ?", dateRange.From)
		}
		if dateRange.To != nil {
			baseQuery = baseQuery.Where("created_at <= ?", dateRange.To)
		}
	}

	if err := baseQuery.Count(&stats.Total).Error; err != nil {
		return nil, fmt.Errorf("error counting total payments: %w", err)
	}

	// Count successful payments
	successQuery := *baseQuery
	if err := successQuery.Where("status = ?", model.PaymentStatusSuccess).Count(&stats.Successful).Error; err != nil {
		return nil, fmt.Errorf("error counting successful payments: %w", err)
	}

	// Count failed payments
	failedQuery := *baseQuery
	if err := failedQuery.Where("status = ?", model.PaymentStatusFailed).Count(&stats.Failed).Error; err != nil {
		return nil, fmt.Errorf("error counting failed payments: %w", err)
	}

	// Count pending payments
	pendingQuery := *baseQuery
	if err := pendingQuery.Where("status = ?", model.PaymentStatusPending).Count(&stats.Pending).Error; err != nil {
		return nil, fmt.Errorf("error counting pending payments: %w", err)
	}

	// Sum successful payment amounts
	var sumResult struct {
		Total *int64
	}
	sumQuery := *baseQuery
	if err := sumQuery.Where("status = ?", model.PaymentStatusSuccess).
		Select("SUM(amount) as total").
		Scan(&sumResult).Error; err != nil {
		return nil, fmt.Errorf("error summing payment amounts: %w", err)
	}

	if sumResult.Total != nil {
		stats.TotalAmount = *sumResult.Total
	}

	// Calculate average
	var averageAmount float64
	if stats.Successful > 0 {
		averageAmount = float64(stats.TotalAmount) / float64(stats.Successful)
	}

	return &model.PaymentSummary{
		TotalPayments:      int32(stats.Total),
		SuccessfulPayments: int32(stats.Successful),
		FailedPayments:     int32(stats.Failed),
		PendingPayments:    int32(stats.Pending),
		TotalAmount:        int32(stats.TotalAmount),
		TotalAmountInCedis: float64(stats.TotalAmount) / 100.0, // Convert pesewa to cedis
		AverageAmount:      averageAmount / 100.0,              // Convert to cedis
	}, nil
}

// PaymentMethodsSummary is the resolver for the paymentMethodsSummary field.
func (r *queryResolver) PaymentMethodsSummary(ctx context.Context, dateRange *model.DateRange) ([]*model.PaymentMethodSummary, error) {
	query := r.DB.Model(&model.Payment{})

	if dateRange != nil {
		if dateRange.From != nil {
			query = query.Where("created_at >= ?", dateRange.From)
		}
		if dateRange.To != nil {
			query = query.Where("created_at <= ?", dateRange.To)
		}
	}

	// Group by payment method and get statistics
	var results []struct {
		Method      string
		Total       int64
		Successful  int64
		TotalAmount int64
	}

	err := query.
		Select("method, COUNT(*) as total, "+
			"SUM(CASE WHEN status = ? THEN 1 ELSE 0 END) as successful, "+
			"SUM(CASE WHEN status = ? THEN amount ELSE 0 END) as total_amount",
			model.PaymentStatusSuccess, model.PaymentStatusSuccess).
		Group("method").
		Scan(&results).Error

	if err != nil {
		return nil, fmt.Errorf("error fetching payment methods summary: %w", err)
	}

	// Convert to GraphQL response format
	summaries := make([]*model.PaymentMethodSummary, len(results))
	for i, result := range results {
		successRate := float64(0)
		if result.Total > 0 {
			successRate = (float64(result.Successful) / float64(result.Total)) * 100
		}

		summaries[i] = &model.PaymentMethodSummary{
			Method:      model.PaymentMethod(result.Method),
			Count:       int32(result.Total),
			TotalAmount: int32(result.TotalAmount),
			SuccessRate: successRate,
		}
	}

	return summaries, nil
}

